{"action":"write_file","path":"solution.py","content":"from ordering import ordered
def coalesce(intervals):
    if not all(start <= end for start, end in intervals):
        raise ValueError('Intervals must be in non-decreasing order of start and non-increasing order of end')
    items=ordered(intervals)
    result=[]
    for start,end in items:
        if result and start <= result[-1][1]: result[-1]=(result[-1][0],end)
        else: result.append((start,end))
    return result
"}

